CREATE TEMPORARY VIEW imp_click_tracking_${grass_region_without_quote} AS
    SELECT
         user_id
        ,platform
        ,app_version
        ,CASE WHEN target_type LIKE '%food%' THEN 'home-daily_discover-food'
              WHEN target_type = 'insurance' THEN 'home-daily_discover-insurance'
              WHEN target_type = 'banner' THEN 'home-daily_discover-banner'
              WHEN target_type = 'campaign' THEN 'home-daily_discover-campaign'
              WHEN target_type = 'shopeepay_near_me' THEN 'home-daily_discover-shopeepay_near_me'
              WHEN target_type = 'digital_product' THEN 'home-daily_discover-digital_product'
         ELSE NULL
         END AS feature_detail
        ,location
        ,operation
        ,SUM(operation_cnt) AS operation_cnt
    FROM srdi_mart.dwd_sr_data_warehouse_platform
    WHERE
         grass_region IN (${grass_region})
        AND local_date = ${local_date}
        AND page_type = 'home'
        AND page_section[0] IN ('daily_discover')
        AND (target_type LIKE '%food%' OR target_type in ('insurance','banner', 'campaign','shopeepay_near_me','digital_product'))
        AND operation in ('click','impression')
    GROUP BY 1,2,3,4,5,6;

--sql_divide_splitter--

CREATE TEMPORARY VIEW user_label_${grass_region_without_quote} AS
    SELECT DISTINCT user_id, life_cycle
    FROM srdi_mart.dim_sr_data_warehouse_user_label
    WHERE grass_region IN (${grass_region}) AND local_date = ${local_date};

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dwm_sr_data_warehouse_dd_others_user_location
PARTITION (grass_region = ${grass_region}, local_date = ${local_date}, operation)
SELECT a.user_id
      ,b.life_cycle
      ,a.platform
      ,a.app_version
      ,a.feature_detail
      ,a.location
      ,a.operation_cnt
      ,NULL AS gmv

      ,a.operation
FROM imp_click_tracking_${grass_region_without_quote} a
LEFT JOIN user_label_${grass_region_without_quote} b
ON a.user_id = b.user_id

