           ,COUNT(DISTINCT order_id) AS operation_cnt
           ,SUM(total_amount * 0.00001) AS gmv
    FROM shopeefood.shopeefood_mart_dwd_my_traffic_external_direct_order_attribute_di
    WHERE dt = ${local_date} AND page_type = 'home' AND page_section = 'daily_discover'
    GROUP BY 1,2,3,4,5

