CREATE TEMPORARY VIEW food_order AS
    SELECT a.grass_region
          ,a.user_id
          ,a.platform
          ,a.app_version
          ,a.location
          ,a.operation_cnt
          ,a.gmv/b.exchange_rate as gmv
    FROM food_order_w_local_gmv a
    LEFT JOIN fx_rate b
    ON a.grass_region = b.grass_region;

