CREATE TEMPORARY VIEW insurance_pdp_view_raw AS
    SELECT  grass_region
           ,grass_date
           ,user_id
           ,CASE
                WHEN inner_from_source IS NOT NULL THEN inner_from_source
                WHEN indirect_from_source IS NOT NULL THEN indirect_from_source
                ELSE direct_from_source
            END AS from_source
           ,row_number() over (partition BY grass_region,grass_date,user_id ORDER BY event_timestamp ASC) AS event_timestamp_rank
    FROM fp_traffic.dws_traffic_insurance_entry_attribution_di
    WHERE page_type = 'insurance_product'
           AND CAST(get_json_object(data, '$.product_id') AS STRING) = '1690597860413811811'
           AND grass_date = ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW insurance_pdp_view AS
      SELECT DISTINCT grass_region, user_id, 'ppv' AS operation, 1 AS operation_cnt, NULL AS gmv
      FROM insurance_pdp_view_raw
      WHERE from_source = 'Daily Discover' AND event_timestamp_rank = 1;

--sql_divide_splitter--
CREATE TEMPORARY VIEW policy AS
select  t1.grass_region
        ,t1.user_id
        ,'order' as operation
        ,SUM(COALESCE(t2.operation_cnt, 0)) as operation_cnt
        ,SUM(COALESCE(t2.gmv, 0)) as gmv
from    (
    select  grass_region
            ,user_id
    from    srdi_mart.dwd_sr_data_warehouse_platform
    where   1 = 1
      AND   page_type = 'home'
      AND   page_section[0] IN ('daily_discover')
      and   target_type = 'insurance'
      AND   user_id > 0
      and   grass_region IN ('ID', 'PH', 'MY', 'TH')
      and   local_date = ${local_date}
      and   operation = 'click'
    group by 1, 2
) t1
inner join (
    select  grass_region
            ,CAST(platform_user_id AS BIGINT) AS user_id
            ,'order' AS operation
            ,COUNT(DISTINCT order_id) AS operation_cnt
            ,SUM(premium_usd) AS gmv
    from    insurance.dwd_spin_reg_policy_info_df
    where   partner_id = 4
      and   grass_date = ${local_date}
      and   DATE(CAST(create_datetime AS TIMESTAMP)) = ${local_date}
      and   grass_region IN ('ID', 'PH', 'MY', 'TH')
    group by 1, 2, 3
) t2
on      t1.grass_region = t2.grass_region
  and   t1.user_id = t2.user_id
group by 1, 2, 3
;

--sql_divide_splitter--

CREATE TEMPORARY VIEW insurance_order_raw AS
    SELECT * FROM insurance_pdp_view
    UNION ALL
    SELECT * FROM policy;

--sql_divide_splitter--

CREATE TEMPORARY VIEW insurance_user_tag AS
    SELECT grass_region
          ,user_id
          ,MAX(platform) AS platform
          ,MAX(app_version) AS app_version
    FROM srdi_mart.dwd_sr_data_warehouse_platform
    WHERE local_date = ${local_date}
        AND page_type = 'home'
        AND page_section[0] IN ('daily_discover')
        AND user_id > 0
        AND operation in ('click','impression')
    GROUP BY 1, 2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW insurance_order AS
    SELECT a.*, platform, app_version
    FROM insurance_order_raw a
    LEFT JOIN insurance_user_tag c
    ON a.grass_region = c.grass_region
       AND a.user_id = c.user_id

--sql_divide_splitter--
CREATE TEMPORARY VIEW dp_loc_order AS
select
    T1.grass_region
    ,user_id
    ,platform
    ,app_version
    ,feature_detail
    ,location
    ,operation
    ,operation_cnt
    ,T1.gmv / T2.exchange_rate as gmv
from
    (
        select
            grass_region
            ,user_id
            ,platform
            ,app_version
            ,case
                when regexp_like(replace(replace(get_json_object(create_event_data,'$.dp_from_source'), 'buyagain', ''),' ', ''), '15_dpheader|15_dpcard') then 'home-daily_discover-digital_product'
                when regexp_like(replace(replace(get_json_object(create_event_data,'$.dp_from_source'), 'buyagain', ''),' ', ''), '15_lsheader|15_lscard') then 'home-daily_discover-shopeepay_near_me'
                else null
            end as feature_detail
            ,null as location
            ,'order' as operation
            ,count(distinct order_id) as operation_cnt
            ,sum(total_amount) * 0.00001 as gmv
        from digitalpurchase.traffic_dwd_dp_order_by_traffic_entrance_di_v2
        where
            date(grass_date) = ${local_date}
            and is_gross_order = 1
            and platform = 1
            and is_bi_excluded = 0
            and user_id is not null
            and l1_external_entrance = 'Daily Discover'
            and regexp_like(
                replace(replace(get_json_object(create_event_data,'$.dp_from_source'), 'buyagain', ''),' ', '')
                ,'15_dpheader|15_dpcard|15_lsheader|15_lscard'
            )
        group by 1, 2, 3, 4, 5
    ) as T1
    left join fx_rate as T2 on T1.grass_region = T2.grass_region ;

--sql_divide_splitter--
CREATE TEMPORARY VIEW campaign_banner_order AS
select
    grass_region
    ,user_id
    ,null as platform
    ,null as app_version
    ,feature_detail
    ,null as location
    ,'order' as operation
    ,sum(order_cnt) as operation_cnt
    ,sum(gmv) as gmv
from
    (
        -- campaign_order
        select
            grass_region
            ,grass_date
            ,user_id
            ,'home-daily_discover-campaign' as feature_detail
            ,order_cnt
            ,gmv
        from
            (
                select
                    grass_region
                    ,grass_date
                    ,user_id
                    ,order_cnt
                    ,gmv
                from
                    (
                        select
                            grass_region
                            ,grass_date
                            ,a.user_id
                            ,pre_step1_view_last_click.page_type as page_type
                            ,pre_step1_view_last_click.page_section as page_section
                            ,pre_step1_view_last_click.target_type as target_type
                            ,sum(place_order_cnt) as order_cnt
                            ,sum(place_order_gmv_usd) as gmv
                        from
                            (
                                select
                                    pre_view_event_id
                                    ,user_id
                                    ,order_id
                                    ,place_order_cnt
                                    ,place_order_gmv
                                    ,place_order_gmv_usd
                                    ,grass_region
                                    ,grass_date
                                from mp_campaign.dwd_eventid_orderid_atc_place_microsite_di__reg_s0_live
                                where
                                    grass_date = ${local_date}
                                    and tz_type = 'local'
                                    and user_id is not null
                            ) a
                            left join (
                                select
                                    user_id
                                    ,pre_step1_view_last_click
                                    ,curr_view_event_id
                                from mp_campaign.dwd_eventid_pre_curr_next_view_microsite_di__reg_s0_live
                                where
                                    grass_date = ${local_date}
                                    and tz_type = 'local'
                                group by 1, 2, 3
                            ) b on a.pre_view_event_id = b.curr_view_event_id
                            and a.user_id = b.user_id
                        group by 1, 2, 3, 4, 5, 6
                    ) temp
                where
                    1 = 1
                    and page_type = 'home'
                    and page_section = 'daily_discover'
                    and target_type = 'campaign'
            ) as temp
        union all
        -- banner_order
        select
            grass_region
            ,grass_date
            ,user_id
            ,'home-daily_discover-banner' as feature_detail
            ,place_order_cnt as order_cnt
            ,place_order_gmv_usd as gmv
        from mp_campaign.dwd_eventid_orderid_atc_place_banner_di__reg_s0_live
        where
            grass_date = ${local_date}
            and tz_type = 'local'
            and banner_type_display_name in ('DD Banner Card 1', 'DD Banner Card 27')
    ) as combined_orders
group by
    user_id
    ,feature_detail
    ,grass_region
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW order_merged AS
    SELECT grass_region
          ,user_id
          ,platform
          ,app_version
          ,'home-daily_discover-food' AS feature_detail
          ,CAST(location AS INT) AS location
          ,'order' AS operation
          ,operation_cnt
          ,gmv
   FROM food_order
   UNION ALL
   SELECT grass_region
         ,user_id
         ,platform
         ,app_version
         ,'home-daily_discover-insurance' AS feature_detail
         ,NULL AS location
         ,operation
         ,operation_cnt
         ,gmv
  FROM insurance_order
  UNION ALL
  SELECT grass_region
        ,user_id
        ,platform
        ,app_version
        ,feature_detail
        ,location
        ,operation
        ,operation_cnt
        ,gmv
  FROM dp_loc_order
  UNION ALL
  SELECT grass_region
        ,user_id
        ,platform
        ,app_version
        ,feature_detail
        ,location
        ,operation
        ,operation_cnt
        ,gmv
  FROM campaign_banner_order
  ;

