CREATE TEMPORARY VIEW user_label AS
    SELECT DISTINCT grass_region, user_id, life_cycle
    FROM srdi_mart.dim_sr_data_warehouse_user_label
    WHERE local_date = ${local_date};

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dwm_sr_data_warehouse_dd_others_user_location
PARTITION (grass_region, local_date, operation)
    SELECT a.user_id
          ,b.life_cycle
          ,a.platform
          ,a.app_version
          ,a.feature_detail
          ,a.location
          ,a.operation_cnt
          ,a.gmv

          ,a.grass_region
          ,CAST(${local_date} AS DATE) AS local_date
          ,a.operation
    FROM order_merged a
    LEFT JOIN user_label b
    ON a.grass_region = b.grass_region
       AND a.user_id = b.user_id
